      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {"label": "Map Invoice Fields"},
      "inputs": {
        "script": (
          "const fields = ($vars.extractInvoice1.output.ExtractionResult"
          " && $vars.extractInvoice1.output.ExtractionResult.ResultsDocument"
          " && $vars.extractInvoice1.output.ExtractionResult.ResultsDocument.Fields) || [];\n"
          "const tables = ($vars.extractInvoice1.output.ExtractionResult"
          " && $vars.extractInvoice1.output.ExtractionResult.ResultsDocument"
          " && $vars.extractInvoice1.output.ExtractionResult.ResultsDocument.Tables) || [];\n"
          "function fv(name) { const f = fields.find(x => x.FieldName === name); return f && f.Values && f.Values[0] || null; }\n"
          "return {\n"
          "  vendorName: fv('VendorName'),\n"
          "  invoiceNumber: fv('InvoiceId'),\n"
          "  invoiceDate: fv('InvoiceDate'),\n"
          "  totalAmount: fv('InvoiceTotal'),\n"
